'use strict';

/**
* Create a k-means clustering results object.
*
* @module @stdlib/ml/base/kmeans/results/float32
*
* @example
* var Results = require( '@stdlib/ml/base/kmeans/results/float32' );
*
* var results = new Results();
* // returns <Results>
*
* results.replicates = 3;
* results.replicate = 1;
* results.metric = 'sqeuclidean';
* results.iterations = 4;
* results.algorithm = 'lloyd';
* results.inertia = 3.28;
* results.k = 4;
* results.samples = 10;
* results.features = 3;
*
* var str = results.toString();
* // returns <string>
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
